def _revive(obj):
    """json.loads `object_hook`: rebuild a value that _mark described."""
    if TYPE_KEY not in obj:
        return obj
    module_name, _, name = obj[TYPE_KEY].rpartition(".")
    # Only allow safe reconstruction of basic types, block arbitrary code execution
    allowed_modules = {
        "decimal": {"Decimal"},
        "datetime": {"date", "timedelta"},
    }
    if module_name not in allowed_modules or name not in allowed_modules[module_name]:
        raise MessageError(f"unauthorized type: {obj[TYPE_KEY]}")
    factory = getattr(importlib.import_module(module_name), name)
    return factory(*obj.get("args", []))

